 async function setActive(r:Row,next:boolean){const ok=await confirm({title:next?'Reactivar cuenta':'Desactivar cuenta',message:`${next?'Reactivar':'Desactivar'} la cuenta de ${r.nombre} ${r.apellido||''} (${r.tipo})? El cambio afecta el acceso y queda auditado.`,danger:!next});if(!ok)return;setBusy(r.id);setMessage('');try{const {error}=await (supabase as any).rpc('admin_set_usuario_activo',{p_usuario_id:r.id,p_activo:next,p_motivo:next?'Reactivación confirmada desde Admin UGO':'Desactivación confirmada desde Admin UGO'});if(error)throw error;const {data:verified,error:verifyError}=await (supabase as any).from('usuarios').select('id,activo').eq('id',r.id).maybeSingle();if(verifyError)throw verifyError;if(!verified||verified.id!==r.id||verified.activo!==next)throw new Error('No se pudo confirmar el estado de la cuenta en Supabase.');await load();setMessage(next?'Usuario reactivado y verificado.':'Usuario desactivado y verificado.')}catch(error){setMessage(error instanceof Error?error.message:'No se pudo cambiar el estado del usuario.')}finally{setBusy('')}}
 async function changeEmail(r:Row){
  if(!canMutate(r))return
  const email=await prompt({title:t('ugoUserEdit.emailTitle'),message:t('ugoUserEdit.emailMessage'),label:t('ugoUserEdit.emailLabel'),inputType:'email',required:true})
  if(email===null)return
  const normalized=email.trim().toLowerCase()
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)){setMessage(t('ugoUserEdit.invalidEmail'));return}
  const ok=await confirm({title:t('ugoUserEdit.emailTitle'),message:t('ugoUserEdit.emailConfirm')+' '+normalized,danger:true})
  if(!ok)return
  setBusy('email:'+r.id);setMessage('')
  try{
    const {data:{session}}=await supabase.auth.getSession()
    if(!session)throw new Error(t('ugoUserEdit.sessionExpired'))
    const response=await fetch('/api/operations?op=admin-change-email',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({userId:r.id,email:normalized})})
    const result=await response.json().catch(()=>({}))
    if(!response.ok||result.success!==true||result.email!==normalized)throw new Error(result.error||t('ugoUserEdit.emailFailed'))
    await load();setMessage(t('ugoUserEdit.emailSaved'))
  }catch(error){setMessage(error instanceof Error?error.message:t('ugoUserEdit.emailFailed'))}
  finally{setBusy('')}
 }
