   {visible.map(r=><article className="ugo-admin-user-card" key={r.id} style={{display:'grid',gridTemplateColumns:'1fr auto',gap:10,border:'1px solid #e5e7eb',borderRadius:15,padding:11,marginBottom:7}}><div><div style={{display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}}><UserProfileAvatar name={r.nombre+' '+(r.apellido||'')} role={r.profilePhotoRole|| (r.tipo==='proveedor'?'provider':'client')} photoPath={r.foto_perfil_path} photoUrl={r.foto_url} size={38}/><strong>{r.nombre} {r.apellido||''}</strong>{r.online&&<span>🟢</span>}<span style={{fontSize:9,padding:'3px 6px',borderRadius:999,background:'#eef2ed'}}>{r.tipo}</span><span style={{fontSize:9,padding:'3px 6px',borderRadius:999,background:r.activo?'#e5f5e9':'#fef3f2',color:r.activo?'#197249':'#b42318'}}>{r.activo?t("uiCopy.short1"):t("uiCopy.short2")}</span></div><div style={{fontSize:11,marginTop:4}}>{r.email||t("uiCopy.expression148")} {r.email_confirmed?'✓':''}</div><div style={{fontSize:10,opacity:.65,marginTop:2}}>{r.telefono||t("verification.noPhone")} · {r.ubicacion||t("uiCopy.expression149")}</div>{r.tipo==='proveedor'&&<div style={{fontSize:10,opacity:.7,marginTop:3}}>{r.categoria?.emoji||'🛠️'} {r.categoria?.nombre||t("adminSurface.noCategory")} {t('admin.users.verification')} {r.verification||t("uiCopy.expression150")} · ⭐ {Number(r.karma||0).toFixed(1)}</div>}<div style={{fontSize:9,opacity:.5,marginTop:3}}>{t('admin.users.lastAccess')} {r.last_sign_in_at?new Date(r.last_sign_in_at).toLocaleString('pt-BR'):t("uiCopy.short5")}</div></div><div className="ugo-admin-user-actions" style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap',justifyContent:'flex-end'}}><button disabled={!!busy||!canMutate(r)} onClick={()=>startEdit(r)} title={!canMutate(r)?'Solo Super Admin puede editar cuentas administrativas':'Editar datos del usuario'} style={{padding:'7px 9px',border:'1px solid #8fa396',borderRadius:9,background:'#fff',fontWeight:800}}>✎ {t("ugoUserEdit.edit")}</button><button onClick={()=>setTraceUser(r)} style={{padding:'7px 9px',border:'1px solid #8fa396',borderRadius:9,background:'#111820',color:'#fff',fontWeight:800}}>{t('screen.admin_users.25')}</button><button disabled={!!busy||!canMutate(r)} onClick={()=>void changeEmail(r)} style={{padding:'7px 9px',border:'1px solid #8fa396',borderRadius:9,background:'#fff'}}>{t('ugoUserEdit.emailAction')}</button><button disabled={!!busy||!canMutate(r)} onClick={()=>void resetPassword(r)} title={!canMutate(r)?'Solo Super Admin puede restablecer cuentas administrativas':'Asignar una nueva contraseña'} style={{padding:'7px 9px',border:'1px solid #8fa396',borderRadius:9,background:'#fff',color:'#2f3d34',fontWeight:800}}>{busy==='password:'+r.id?t("uiCopy.short42"):t("uiCopy.expression151")}</button>{r.activo?<button disabled={!!busy||!canMutate(r)} onClick={()=>setActive(r,false)} title={!canMutate(r)?'Solo Super Admin puede modificar cuentas administrativas':undefined} style={{padding:'7px 9px',border:'1px solid #f4b4b4',borderRadius:9,background:'#fff',color:'#b42318'}}>{t('screen.admin_users.26')}</button>:<button disabled={!!busy||!canMutate(r)} onClick={()=>setActive(r,true)} title={!canMutate(r)?'Solo Super Admin puede modificar cuentas administrativas':undefined} style={{padding:'7px 9px',border:0,borderRadius:9,background:'#197249',color:'#fff'}}>{t('screen.admin_users.27')}</button>}</div></article>)}
